2. 
3. const { minify } = require('terser');
4. const { isMatch } = require('micromatch');
5. 
6. module.exports = function(str, data) {
7.   const options = this.config.uglify;
8. 
9.   const { path } = data;
10.   const { exclude } = options;
11. 
12.   if (path && exclude && exclude.length) {
13.     if (isMatch(path, exclude, { basename: true })) return str;
14.   }
15. 
16.   // Remove unsupported options for Terser
17.   const jsOptions = Object.assign({}, options);
18.   delete jsOptions.exclude;
19.   delete jsOptions.es6;
20. 
21.   const { code } = minify(str, jsOptions);
22. 
23.   return code;
24. };
25.

