 'use strict';

 const { minify } = require('terser');
 const { isMatch } = require('micromatch');
 const { getPromiseDetails } = process.binding('util'); // eslint-disable-line node/no-deprecated-api

 function getCode(result) {
   if (typeof result.then !== 'function') return result.code;

   if (typeof getPromiseDetails !== 'function') {
     return result.then(({ code }) => code);
   }

   const [state, value] = getPromiseDetails(result);

   if (state === 1) return value.code;
   if (state === 2) throw value;

   return result.then(({ code }) => code);
 }

 module.exports = function(str, data) {
   const options = this.config.uglify;

   const { path } = data;
   const { exclude } = options;

   if (path && exclude && exclude.length) {
     if (isMatch(path, exclude, { basename: true })) return str;
   }

   // Remove unsupported options for Terser
   const jsOptions = Object.assign({}, options);
   delete jsOptions.exclude;
   delete jsOptions.es6;

   return getCode(minify(str, jsOptions));
 };

